<span class="line"><span style="color:#ABB2BF;">    duration_by_cmd </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> defaultdict</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">list</span><span style="color:#ABB2BF;">)</span></span>
