<span class="line"><span style="color:#98C379;">        &#39;redis_custom_evicted_keys&#39;</span><span style="color:#ABB2BF;">: info_stats.</span><span style="color:#61AFEF;">get</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;evicted_keys&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">),</span></span>
