<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> push_to_gateway</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">metrics</span><span style="color:#ABB2BF;">):</span></span>
