<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> name, value </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> metrics.</span><span style="color:#61AFEF;">items</span><span style="color:#ABB2BF;">():</span></span>
